// Roughly what the ESP32 Arduino core sets up for you:
xTaskCreatePinnedToCore(
    loopTask,          // runs setup() once, then loop() forever
    "loopTask",
    8192,              // stack, in BYTES on ESP32
    NULL,
    1,                 // priority 1 — barely above idle
    NULL,
    ARDUINO_RUNNING_CORE   // = Core 1
);

xTaskCreatePinnedToCore(
    sensorTask,     // 1. function: void fn(void*), never returns
    "sensor",       // 2. name — shows up in panics and debug output
    4096,           // 3. stack depth — BYTES on ESP32
    NULL,           // 4. parameter passed to the function
    2,              // 5. priority — 0 = idle, higher = more urgent
    &sensorHandle,  // 6. handle, for later control (or NULL)
    1               // 7. core: 0, 1, or tskNO_AFFINITY
);

void sensorTask(void *pv) {
    for (;;) {                       // a task NEVER returns
        readSensor();
        vTaskDelay(pdMS_TO_TICKS(2000));   // yields the CPU
    }
}

struct Reading { float temp; float humidity; uint32_t ts; };

QueueHandle_t readingQ = xQueueCreate(5, sizeof(Reading));  // depth, item size

// producer — sensor task
Reading r = { t, h, millis() };
if (xQueueSend(readingQ, &r, 0) != pdTRUE) {
    droppedReadings++;        // queue full: DECIDE what this means
}

// consumer — network task
Reading got;
if (xQueueReceive(readingQ, &got, pdMS_TO_TICKS(100)) == pdTRUE) {
    publish(got);             // blocked, not spinning, while waiting
}

SemaphoreHandle_t i2cMutex = xSemaphoreCreateMutex();

// any task touching Wire must hold it
if (xSemaphoreTake(i2cMutex, pdMS_TO_TICKS(50)) == pdTRUE) {
    gesture.read();               // critical section: keep it SHORT
    xSemaphoreGive(i2cMutex);     // ALWAYS release — every path
} else {
    busyCount++;                  // could not get the bus — handle it
}

// minimum free stack this task has EVER had, in BYTES on ESP32
UBaseType_t freeBytes = uxTaskGetStackHighWaterMark(NULL);
Serial.printf("task=%s hwm=%u heap=%u\n",
              pcTaskGetName(NULL), freeBytes, ESP.getFreeHeap());
